import React, { useState, useEffect } from "react";
import axios from "axios";
import "./styles.css";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function App() {
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loginIdentifier, setLoginIdentifier] = useState(""); // username or email
  const [message, setMessage] = useState("");
  const [googleUser, setGoogleUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [profile, setProfile] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem("token"));
  const [currentPage, setCurrentPage] = useState("login"); // "login" or "register"
  const [showForgot, setShowForgot] = useState(false);
  const [resetStep, setResetStep] = useState(1); // 1: send code, 2: enter code + new pw
  const [resetEmail, setResetEmail] = useState("");
  const [resetCode, setResetCode] = useState("");
  const [resetNewPassword, setResetNewPassword] = useState("");
  const [resetConfirmNewPassword, setResetConfirmNewPassword] = useState("");

  // Validation helpers
  const isEmailValid = (value) => /[^\s@]+@[^\s@]+\.[^\s@]+/.test(value);
  const passHasLen = password.length >= 8;
  const passHasUpper = /[A-Z]/.test(password);
  const passHasLower = /[a-z]/.test(password);
  const passHasNumber = /\d/.test(password);
  const passHasSpecial = /[^A-Za-z0-9]/.test(password);
  const isPasswordStrong = passHasLen && passHasUpper && passHasLower && passHasNumber && passHasSpecial;

  // Reset password validators
  const rPassHasLen = resetNewPassword.length >= 8;
  const rPassHasUpper = /[A-Z]/.test(resetNewPassword);
  const rPassHasLower = /[a-z]/.test(resetNewPassword);
  const rPassHasNumber = /\d/.test(resetNewPassword);
  const rPassHasSpecial = /[^A-Za-z0-9]/.test(resetNewPassword);
  const isResetPasswordStrong = rPassHasLen && rPassHasUpper && rPassHasLower && rPassHasNumber && rPassHasSpecial;

  const register = async () => {
    if (!username || !email || !password || !confirmPassword) {
      setMessage("All fields are required");
      return;
    }

    if (!isEmailValid(email)) {
      setMessage("Please enter a valid email address");
      return;
    }

    if (password !== confirmPassword) {
      setMessage("Passwords do not match");
      return;
    }

    if (!isPasswordStrong) {
      setMessage("Please meet the password requirements below");
      return;
    }

    try {
      await axios.post("http://localhost:8000/register", {
        username,
        email,
        password,
      });
      
      // Show success message and redirect to login page
      setMessage("Registration successful! Please login with your credentials.");
      setCurrentPage("login");
      
      // Clear form fields
      setUsername("");
      setEmail("");
      setPassword("");
      setConfirmPassword("");
      
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error registering");
    }
  };

  const login = async () => {
    if (!loginIdentifier || !password) {
      setMessage("Please enter your username or email and password");
      return;
    }
    try {
      const payload = loginIdentifier.includes("@")
        ? { email: loginIdentifier, password }
        : { username: loginIdentifier, password };
      const res = await axios.post("http://localhost:8000/login", payload);
      
      // Save token
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      setToken(access_token);
      setIsLoggedIn(true);
      setMessage(resMessage);
      
      // Fetch user profile
      fetchProfile();
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error logging in");
    }
  };
  
  const logout = () => {
    localStorage.removeItem("token");
    setToken("");
    setIsLoggedIn(false);
    setProfile(null);
    setGoogleUser(null);
    setMessage("Logged out successfully");
    setCurrentPage("login");
    setShowForgot(false);
    setLoginIdentifier("");
    setPassword("");
  };
  
  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        // Token expired or invalid
        logout();
      }
    }
  };

  // Forgot password flow
  const sendResetCode = async () => {
    if (!resetEmail || !isEmailValid(resetEmail)) {
      setMessage("Enter a valid email to receive a code");
      return;
    }
    try {
      await axios.post("http://localhost:8000/forgot-password", { email: resetEmail });
      setMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    } catch (err) {
      // Always generic
      setMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    }
  };

  const resetPassword = async () => {
    if (!resetCode || !resetNewPassword || !resetConfirmNewPassword) {
      setMessage("All fields are required");
      return;
    }
    if (resetNewPassword !== resetConfirmNewPassword) {
      setMessage("Passwords do not match");
      return;
    }
    if (!isResetPasswordStrong) {
      setMessage("Please meet the password requirements below");
      return;
    }
    try {
      await axios.post("http://localhost:8000/reset-password", {
        email: resetEmail,
        code: resetCode,
        new_password: resetNewPassword,
      });
      setMessage("Password reset successful. Please login with your new password.");
      // Reset forgot state and go back to login
      setShowForgot(false);
      setCurrentPage("login");
      setLoginIdentifier(resetEmail); // prefill email
      setResetEmail("");
      setResetCode("");
      setResetNewPassword("");
      setResetConfirmNewPassword("");
    } catch (err) {
      setMessage(err.response?.data?.detail || "Unable to reset password. Check your code and try again.");
    }
  };

  // Handle Google Sign-In response
  const handleGoogleResponse = async (response) => {
    try {
      const credential = response.credential;
      const payload = JSON.parse(atob(credential.split('.')[1]));
      
      // Extract user info from the JWT payload
      const googleUserInfo = {
        email: payload.email,
        name: payload.name
      };
      
      setGoogleUser(googleUserInfo);
      
      // Send to backend
      const res = await axios.post("http://localhost:8000/google-login", googleUserInfo);
      
      // Save token
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      setToken(access_token);
      setIsLoggedIn(true);
      setMessage(resMessage);
      
      // Fetch user profile
      fetchProfile();
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error with Google Sign-In");
    }
  };

  // Initialize Google Sign-In
  useEffect(() => {
    // Fetch Google Client ID from backend
    const fetchGoogleClientId = async () => {
      try {
        const response = await axios.get("http://localhost:8000/google-client-id");
        const clientId = response.data.client_id;
        
        if (window.google && clientId) {
          window.google.accounts.id.initialize({
            client_id: clientId,
            callback: handleGoogleResponse,
          });

          window.google.accounts.id.renderButton(
            document.getElementById("google-signin"),
            { theme: "outline", size: "large", text: "signin_with", shape: "rectangular" }
          );
        }
      } catch (err) {
        console.error("Error fetching Google Client ID:", err);
        setMessage("Error initializing Google Sign-In");
      }
    };

    fetchGoogleClientId();
  }, []);
  
  // Fetch user profile on component mount if token exists
  useEffect(() => {
    if (token) {
      fetchProfile();
    }
  }, []);

  // Determine message class based on content
  const getMessageClass = () => {
    if (!message) return "";
    return message.toLowerCase().includes("error") ? "message error" : "message success";
  };

  // Clear message when switching pages
  const switchToPage = (page) => {
    setCurrentPage(page);
    setMessage("");
    setUsername("");
    setEmail("");
    setPassword("");
    setConfirmPassword("");
    setLoginIdentifier("");
    setShowForgot(false);
    setResetStep(1);
    setResetEmail("");
    setResetCode("");
    setResetNewPassword("");
    setResetConfirmNewPassword("");
  };

  return (
    <div className="container">
      <h1 className="app-title">Welcome</h1>
      
      {!isLoggedIn ? (
        // Authentication Pages
        <>
          {/* Page Navigation */}
          <div className="page-tabs">
            <button 
              className={`tab-button ${currentPage === "login" ? "active" : ""}`}
              onClick={() => switchToPage("login")}
            >
              Login
            </button>
            <button 
              className={`tab-button ${currentPage === "register" ? "active" : ""}`}
              onClick={() => switchToPage("register")}
            >
              Register
            </button>
          </div>

          {currentPage === "login" ? (
            // Login or Forgot Password Page
            <div className="auth-page">
              {!showForgot ? (
                <>
                  <h2 className="page-title">Welcome Back!</h2>
                  <p className="page-description">Sign in with your username or email</p>
                  
                  <div className="input-group">
                    <label className="input-label">Username or Email</label>
                    <input
                      className="input-field"
                      placeholder="Enter your username or email"
                      value={loginIdentifier}
                      onChange={(e) => setLoginIdentifier(e.target.value)}
                    />
                  </div>
                  
                  <div className="input-group">
                    <label className="input-label">Password</label>
                    <input
                      className="input-field"
                      type="password"
                      placeholder="Enter your password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                  </div>
                  
                  <button className="btn btn-primary login-btn" onClick={login}>
                    Sign In
                  </button>

                  <div className="login-link">
                    <button className="link-button" onClick={() => { setShowForgot(true); setMessage(""); }}>
                      Forgot password?
                    </button>
                  </div>
                  
                  <div className="divider">
                    <span>OR</span>
                  </div>
                  
                  <div className="google-signin-container">
                    <div id="google-signin"></div>
                  </div>
                </>
              ) : (
                <>
                  <h2 className="page-title">Reset your password</h2>
                  {resetStep === 1 ? (
                    <>
                      <p className="page-description">Enter your account email to receive a 6-digit code</p>
                      <div className="input-group">
                        <label className="input-label">Email</label>
                        <input
                          className="input-field"
                          type="email"
                          placeholder="you@example.com"
                          value={resetEmail}
                          onChange={(e) => setResetEmail(e.target.value)}
                        />
                      </div>
                      <button className="btn btn-primary login-btn" onClick={sendResetCode}>
                        Send Reset Code
                      </button>
                      <div className="login-link">
                        <button className="link-button" onClick={() => setShowForgot(false)}>Back to login</button>
                      </div>
                    </>
                  ) : (
                    <>
                      <p className="page-description">Enter the code sent to your email and set a new password</p>
                      <div className="input-group">
                        <label className="input-label">Verification Code</label>
                        <input
                          className="input-field"
                          placeholder="6-digit code"
                          value={resetCode}
                          onChange={(e) => setResetCode(e.target.value)}
                        />
                      </div>
                      <div className="input-group">
                        <label className="input-label">New Password</label>
                        <input
                          className="input-field"
                          type="password"
                          placeholder="Create a strong password"
                          value={resetNewPassword}
                          onChange={(e) => setResetNewPassword(e.target.value)}
                        />
                        <ul className="requirements-list">
                          <li className={`req-item ${rPassHasLen ? 'pass' : 'fail'}`}>At least 8 characters</li>
                          <li className={`req-item ${rPassHasUpper ? 'pass' : 'fail'}`}>One uppercase letter (A-Z)</li>
                          <li className={`req-item ${rPassHasLower ? 'pass' : 'fail'}`}>One lowercase letter (a-z)</li>
                          <li className={`req-item ${rPassHasNumber ? 'pass' : 'fail'}`}>One number (0-9)</li>
                          <li className={`req-item ${rPassHasSpecial ? 'pass' : 'fail'}`}>One special character (!@#$…)</li>
                        </ul>
                      </div>
                      <div className="input-group">
                        <label className="input-label">Confirm New Password</label>
                        <input
                          className="input-field"
                          type="password"
                          placeholder="Confirm your new password"
                          value={resetConfirmNewPassword}
                          onChange={(e) => setResetConfirmNewPassword(e.target.value)}
                        />
                      </div>
                      <button className="btn btn-primary login-btn" onClick={resetPassword}>
                        Reset Password
                      </button>
                      <div className="login-link">
                        <button className="link-button" onClick={() => { setShowForgot(false); setResetStep(1); }}>Back to login</button>
                      </div>
                    </>
                  )}
                </>
              )}
            </div>
          ) : (
            // Register Page
            <div className="auth-page">
              <h2 className="page-title">Create Account</h2>
              <p className="page-description">Join us and start your journey</p>
              
              <div className="input-group">
                <label className="input-label">Username</label>
                <input
                  className="input-field"
                  placeholder="Choose a username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>

              <div className="input-group">
                <label className="input-label">Email</label>
                <input
                  className="input-field"
                  type="email"
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
                {email && (
                  <div className={`helper-text ${isEmailValid(email) ? 'valid' : 'invalid'}`}>
                    {isEmailValid(email) ? 'Email looks good' : 'Enter a valid email address'}
                  </div>
                )}
              </div>
              
              <div className="input-group">
                <label className="input-label">Password</label>
                <input
                  className="input-field"
                  type="password"
                  placeholder="Create a strong password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <ul className="requirements-list">
                  <li className={`req-item ${passHasLen ? 'pass' : 'fail'}`}>At least 8 characters</li>
                  <li className={`req-item ${passHasUpper ? 'pass' : 'fail'}`}>One uppercase letter (A-Z)</li>
                  <li className={`req-item ${passHasLower ? 'pass' : 'fail'}`}>One lowercase letter (a-z)</li>
                  <li className={`req-item ${passHasNumber ? 'pass' : 'fail'}`}>One number (0-9)</li>
                  <li className={`req-item ${passHasSpecial ? 'pass' : 'fail'}`}>One special character (!@#$…)</li>
                </ul>
              </div>

              <div className="input-group">
                <label className="input-label">Confirm Password</label>
                <input
                  className="input-field"
                  type="password"
                  placeholder="Confirm your password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                />
                {confirmPassword && (
                  <div className={`helper-text ${password && confirmPassword === password ? 'valid' : 'invalid'}`}>
                    {password && confirmPassword === password ? 'Passwords match' : 'Passwords do not match'}
                  </div>
                )}
              </div>
              
              <button className="btn btn-secondary register-btn" onClick={register}>
                Create Account
              </button>
              
              <p className="login-link">
                Already have an account?{" "}
                <button 
                  className="link-button" 
                  onClick={() => switchToPage("login")}
                >
                  Sign in here
                </button>
              </p>
            </div>
          )}
        </>
      ) : (
        // User Profile
        <div className="profile-container">
          <h2>User Profile</h2>
          {profile && (
            <div className="profile-info">
              {profile.username && <p><strong>Username:</strong> {profile.username}</p>}
              {profile.name && <p><strong>Name:</strong> {profile.name}</p>}
              {profile.email && <p><strong>Email:</strong> {profile.email}</p>}
              <p><strong>Auth Type:</strong> {profile.auth_type}</p>
              <button className="btn btn-danger" onClick={logout}>Logout</button>
            </div>
          )}
        </div>
      )}
      
      {message && <div className={getMessageClass()}>{message}</div>}
      
      {googleUser && !profile && (
        <div className="user-info">
          <h3>Signed in Successfully</h3>
          <p>Welcome, <strong>{googleUser.name}</strong></p>
          <p className="user-email">{googleUser.email}</p>
        </div>
      )}
    </div>
  );
}

export default App;
